    local function ref_sig(compute_initial_part, compute_signature, compute_quotient, states, make_state_set)
        local parts = {}
        for state, _ in pairs(states) do
            local part = compute_initial_part(state)
            if not parts[part] then
                parts[part] = make_state_set()
