        local changed = true
        while changed do
            changed = false
            -- snapshot the partition for this round: signatures must be
            -- computed against one consistent version, otherwise later
            -- blocks see a half-updated map and states could merge that
            -- are not bisimilar
            local round_state_to_set = {}
            for state, set in pairs(state_to_set) do
                round_state_to_set[state] = set
            end
            local todo = {}
            for k,_ in pairs(partition) do
                table.insert(todo, k)
