                partition[set_str] = nil
                local signatures = {}
                for state, _ in pairs(set) do
                    local signature = compute_signature(state, round_state_to_set)
                    if not signatures[signature] then
                        signatures[signature] = make_state_set()
                    end
                    signatures[signature][state] = true
                end
                for _, new_set in pairs(signatures) do
                    partition[tostring(new_set)] = new_set
                    for state, _ in pairs(new_set) do
                        state_to_set[state] = new_set
                    end
                    if util.count_entries(signatures) > 1 then
                        changed = true
