                end
            end
        end
        return compute_quotient(partition, state_to_set, states)
    end

    function automata.ref_sig_dfa(dfa)
        assert(automata.is_finished_dfa(dfa))
        dfa = automata.complete_dfa(dfa)

        local function compute_initial_part_dfa(state)
            if dfa:is_accepting(state) then
                return "acc"
            else
                return "nacc"
            end
        end

        local function compute_signature_dfa(state, state_to_set)
            local result = {}
            for symbol,_ in pairs(dfa:get_symbols()) do
                table.insert(result, symbol .. "=" .. tostring(state_to_set[dfa:get_to_states(state, symbol)]))
            end
            local result =  "{" .. table.concat(result, ",") .. "}"
            return result
        end

        local function compute_quotient_dfa(partition, state_to_set, _)
            local result = automata.make_dfa()
            for set_str, set in pairs(partition) do
                result:add_state(set_str)
                local representative = automata.get_state_set_member(set)
                if dfa:is_accepting(representative) then
                    result:set_accepting(set_str, true)
                end
            end
            result:set_initial(tostring(state_to_set[dfa:get_initial()]), true)
            for set_str, set in pairs(partition) do
                local representative = automata.get_state_set_member(set)
                for symbol,_ in pairs(dfa:get_symbols()) do
                    result:add_transition(set_str, symbol, tostring(state_to_set[dfa:get_to_states(representative, symbol)]))
                end
            end
            return result
        end
        return ref_sig(compute_initial_part_dfa, compute_signature_dfa, compute_quotient_dfa, dfa:get_states(),
                function() return dfa:make_state_set() end)
    end

    function automata.regexp_to_nfa_lambda(regexp)
        assert(automata.is_regexp(regexp))

        local state_number = 1

        local function next_state_name()
            local result = "s" .. tostring(state_number)
            state_number = state_number + 1
            return result
        end

        local function get_initial(nfa)
            return nfa:get_initial()
        end

        local function get_accepting(nfa)
            for state, _ in pairs(nfa:get_states()) do
                if nfa:is_accepting(state) then
                    return state
                end
            end
        end

        local function copy_nfa_to(from, to)
            for state, _ in pairs(from:get_states()) do
                to:add_state(state)
            end
            for _, transition in ipairs(from:get_transitions()) do
                to:add_transition(transition.from, transition.label, transition.target)
            end
        end

        local function recurse(regexp)
            local init_name = next_state_name()
            local final_name = next_state_name()
            local nfa = automata.make_nfa(true)
            nfa:add_state(init_name)
            nfa:add_state(final_name)
            nfa:set_initial(init_name, true)
            nfa:set_accepting(final_name, true)
            if regexp:get_type() == "regexp_blank" then
                nfa:add_transition(init_name, "", final_name)
            elseif regexp:get_type() == "regexp_empty" then
            elseif regexp:get_type() == "regexp_primitive" then
                nfa:add_transition(init_name, regexp:get_inner(), final_name)
            elseif regexp:get_type() == "regexp_sequence" then
                local nfa_left = recurse(regexp:get_left())
                copy_nfa_to(nfa_left, nfa)
                local nfa_right = recurse(regexp:get_right())
                copy_nfa_to(nfa_right, nfa)
                local left_init = get_initial(nfa_left)
                local left_accepting = get_accepting(nfa_left)
                local right_init = get_initial(nfa_right)
                local right_accepting = get_accepting(nfa_right)
                nfa:add_transition(init_name, "", left_init)
                nfa:add_transition(left_accepting, "", right_init)
                nfa:add_transition(right_accepting, "", final_name)
            elseif regexp:get_type() == "regexp_choice" then
                local nfa_left = recurse(regexp:get_left())
                copy_nfa_to(nfa_left, nfa)
                local nfa_right = recurse(regexp:get_right())
                copy_nfa_to(nfa_right, nfa)
                local left_init = get_initial(nfa_left)
                local left_accepting = get_accepting(nfa_left)
                local right_init = get_initial(nfa_right)
                local right_accepting = get_accepting(nfa_right)
                nfa:add_transition(init_name, "", left_init)
                nfa:add_transition(init_name, "", right_init)
                nfa:add_transition(left_accepting, "", final_name)
                nfa:add_transition(right_accepting, "", final_name)
            elseif regexp:get_type() == "regexp_repetition" then
                local nfa_inner = recurse(regexp:get_inner())
                copy_nfa_to(nfa_inner, nfa)
                local inner_init = get_initial(nfa_inner)
                local inner_accepting = get_accepting(nfa_inner)
                nfa:add_transition(init_name, "", inner_init)
                nfa:add_transition(init_name, "", final_name)
                nfa:add_transition(inner_accepting, "", final_name)
                nfa:add_transition(inner_accepting, "", inner_init)
            elseif regexp:get_type() == "regexp_plus" then
                local nfa_inner = recurse(regexp:get_inner())
                copy_nfa_to(nfa_inner, nfa)
                local inner_init = get_initial(nfa_inner)
                local inner_accepting = get_accepting(nfa_inner)
                nfa:add_transition(init_name, "", inner_init)
                nfa:add_transition(inner_accepting, "", final_name)
                nfa:add_transition(inner_accepting, "", inner_init)
            else
                assert(false)
            end
            return nfa
        end

        return recurse(regexp)
    end

    function automata.rename_automaton_states(automaton, map)
        local new_automaton
        if automaton:get_type() == "dfa" then
            new_automaton = automata.make_dfa()
        elseif automaton:get_type() == "nfa" then
            new_automaton = automata.make_nfa(false)
        elseif automaton:get_type() == "nfa-lambda" then
            new_automaton = automata.make_nfa(true)
        end
        for state, _ in pairs(automaton:get_states()) do
            local new_state = map[state]
            new_automaton:add_state(new_state)
            if automaton:is_accepting(state) then
                new_automaton:set_accepting(tostring(new_state), true)
            end
        end
        new_automaton:set_initial(map[automaton:get_initial()], true)
        for _, transition in ipairs(automaton:get_transitions()) do
            new_automaton:add_transition(map[transition.from], transition.label, map[transition.target])
        end
        return new_automaton
    end

    function automata.simplify_state_names(automaton)
        local statenamemap = {}

        setmetatable(statenamemap, { number = 1, __index = function(table, key)
            local result = "s" .. tostring(getmetatable(table).number)
            getmetatable(table).number = getmetatable(table).number + 1
            table[key] = result
            return result
        end})
        return automata.rename_automaton_states(automaton, statenamemap)
    end

    local function to_dfa_if_possible(l1)
        if automata.is_regexp(l1) then
            l1 = automata.regexp_to_nfa_lambda(l1)
        end
        if automata.is_finished_nfa_lambda(l1) then
            l1 = automata.nfa_to_dfa(l1)
        end
        return l1
    end

    function automata.intersec_regular(dfa1, dfa2)
        assert(dfa1)
        assert(dfa2)
        dfa1 = to_dfa_if_possible(dfa1)
        dfa2 = to_dfa_if_possible(dfa2)

        local function make_state_pair(state1, state2)
            assert(type(state1) == "string", type(state1))
            assert(type(state2) == "string", type(state2))
            local result = { state1 = state1, state2 = state2 }
            setmetatable(result, { __tostring = function(p)
                return "(" .. p.state1 .. "," .. p.state2 .. ")"
            end })
            return result
        end

        local function make_new_initial_state()
            assert(dfa1:get_initial())
            assert(dfa2:get_initial())
            return make_state_pair(dfa1:get_initial(), dfa2:get_initial())
        end

        local function get_pair_successors(pair, symbol)
            assert(pair.state1)
            assert(pair.state2)
            local succ_1 = dfa1:get_to_states(pair.state1, symbol)
            local succ_2 = dfa2:get_to_states(pair.state2, symbol)
            assert(succ_1, symbol)
            assert(succ_2, symbol)
            return make_state_pair(succ_1, succ_2)
        end

        local symbols = make_union(dfa1.symbols, dfa2.symbols)

        dfa1 = automata.complete_dfa(dfa1, symbols)
        dfa2 = automata.complete_dfa(dfa2, symbols)

        local todo = {}
        local todo_index = 1
        local states = {}
        local new_init = make_new_initial_state()
        states[tostring(new_init)] = new_init
        table.insert(todo, tostring(new_init))

        local new_dfa = automata.make_dfa()
        for symbol,_ in pairs(symbols) do
            new_dfa:add_symbol(symbol)
        end
        new_dfa:add_state(tostring(new_init))
        new_dfa:set_initial(tostring(new_init), true)
        if dfa1:is_accepting(dfa1:get_initial()) and dfa2:is_accepting(dfa2:get_initial()) then
            new_dfa:set_accepting(tostring(new_init), true)
        end

        while todo_index <= #todo do
            local state = todo[todo_index]
            for symbol,_ in pairs(symbols) do
                local succ = get_pair_successors(states[state], symbol)
                if not states[tostring(succ)] then
                    new_dfa:add_state(tostring(succ))
                    table.insert(todo, tostring(succ))
                    states[tostring(succ)] = succ
                    if dfa1:is_accepting(succ.state1) and dfa2:is_accepting(succ.state2) then
                        new_dfa:set_accepting(tostring(succ), true)
                    end
                end
                new_dfa:add_transition(tostring(state), symbol, tostring(succ))
            end
            todo_index = todo_index + 1
        end
        new_dfa = automata.simplify_state_names(new_dfa)
        return new_dfa
    end

    function automata.compare_languages(l1, l2, deadline)
        assert(l1)
        assert(l2)
        l1 = to_dfa_if_possible(l1)
        l2 = to_dfa_if_possible(l2)
        if automata.is_finished_dfa(l1) and automata.is_finished_dfa(l2) then
            return automata.compare_dfa(l1, l2)
        else
            local l1words, l2words = automata.make_word_generator(l1, deadline), automata.make_word_generator(l2, deadline)
            local l1done
            local l2done
            -- generators report "capped" when the explored configuration
            -- space hit its bound; the verdict stays heuristic ("=" only
            -- means no witness found within the sample) either way
            local l1truncated, l2truncated
            local cex1, cex2
            for _=1,100 do
                if (l1done or cex1) and (l2done or cex2) then
                    break
                end
                if deadline and os.clock() > deadline then
                    l1truncated, l2truncated = true, true
                    break
                end
                if not l1done and not cex1 then
                    local word1, gen_capped = l1words()
                    if word1 then
                        local acceptance1, _, capped = automata.is_accepted(l2, word1, deadline)
                        -- a capped search is not a rejection: only a
                        -- definite non-member counts as a witness
                        if acceptance1 == false and not capped then
                            cex1 = word1
                        end
                    else
                        l1done = true
                        l1truncated = gen_capped ~= nil
                    end
                end
                if not l2done and not cex2 then
                    local word2, gen_capped = l2words()
                    if word2 then
                        local acceptance2, _, capped = automata.is_accepted(l1, word2, deadline)
                        if acceptance2 == false and not capped then
                            cex2 = word2
                        end
                    else
                        l2done = true
                        l2truncated = gen_capped ~= nil
                    end
                end
            end
            local compare = get_compare_symbols(cex1, cex2)
            return compare, cex1, cex2, (l1truncated or l2truncated) and "truncated" or nil
        end
    end
end
